package main

import (
	"context"
	"errors"
	"sync"
	"time"
)

type Job struct {
	ID   string
	Data []byte
}

type Result struct {
	JobID string
	Err   error
}

type Pool struct {
	workers int
	jobs    chan Job
	results chan Result
	wg      sync.WaitGroup
}

func NewPool(workers int) *Pool {
	return &Pool{
		workers: workers,
		jobs:    make(chan Job, workers*2),
		results: make(chan Result, workers*2),
	}
}

func (p *Pool) Process(ctx context.Context, job Job) Result {
	select {
	case <-ctx.Done():
		return Result{JobID: job.ID, Err: ctx.Err()}
	case p.jobs <- job:
	}
	select {
	case <-ctx.Done():
		return Result{JobID: job.ID, Err: ctx.Err()}
	case res := <-p.results:
		return res
	}
}

