package main

import (
	"context"
	"fmt"
	"testing"
	"time"
)

func TestPoolConcurrency(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	pool := NewPool(4)
	for i := 0; i < 10; i++ {
		job := Job{ID: fmt.Sprintf("job-%d", i)}
		go func(j Job) {
			_ = pool.Process(ctx, j)
		}(job)
	}
}
